<script>(function(){var root=document.getElementById('payoutPanel');if(!root)return;var rows=[].slice.call(root.querySelectorAll('.pyo-row')),q=document.getElementById('pyoSearch'),status=document.getElementById('pyoStatus');function set(id,v){var e=document.getElementById(id);if(e)e.textContent=v}function select(r){rows.forEach(function(x){x.classList.toggle('is-selected',x===r)});var d=r.dataset,s=d.status.charAt(0).toUpperCase()+d.status.slice(1),link=document.getElementById('pdViewDetails');set('pdId',d.id);set('pdId2',d.id);set('pdStatus',s);set('pdStatus2',s);set('pdAmount',d.amount);set('pdAmount2',d.amount);set('pdPaid',(d.status==='paid'?'Paid on ':'Updated ')+d.date);set('pdDate',d.date);set('pdRef',d.ref);set('pdOrders',d.orders);set('pdTotal',d.total);set('pdFees','-'+d.fees);set('pdTime1',d.date);if(link)link.href='payout_detail.php?id='+encodeURIComponent(d.oid)}function filter(){var text=(q.value||'').toLowerCase(),st=status.value,count=0;rows.forEach(function(r){var show=(!text||r.dataset.search.indexOf(text)>-1)&&(!st||r.dataset.status===st);r.hidden=!show;if(show)count++});set('pyoCount',count+' payouts')}rows.forEach(function(r){r.addEventListener('click',function(){select(r)})});q.addEventListener('input',filter);status.addEventListener('change',filter);document.getElementById('pyoReset').addEventListener('click',function(){q.value='';status.value='';filter()});document.getElementById('pyoExport').addEventListener('click',function(){var lines=['Payout ID,Date,Status,Amount,Reference'];rows.filter(function(r){return!r.hidden}).forEach(function(r){lines.push([r.dataset.id,r.dataset.date,r.dataset.status,r.dataset.amount,r.dataset.ref].map(function(v){return '"'+String(v).replace(/"/g,'""')+'"'}).join(','))});var b=new Blob([lines.join('\n')],{type:'text/csv'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='payouts.csv';a.click();setTimeout(function(){URL.revokeObjectURL(a.href)},500)});if(rows[0])select(rows[0])})();</script>
